/* the price a shop would actually write: round to the step local prices use */
function nice(v, cur){
  if(v == null) return null;
  const st = cur==="COP" ? (v<10000?500:1000)
    : cur==="CLP" || cur==="ARS" ? (v<10000?500:1000)
    : cur==="MXN" ? (v<100?5:v<1000?10:50)
    : (cur==="PEN" || cur==="BRL") ? (v<50?1:v<200?5:10)
    : (v<10?0.5:v<50?1:v<200?5:10);     // USD, CAD
  return Math.max(st, Math.round(v/st)*st);
}
const local = (country, co) => co==null ? null : (country==="CO" ? co : nice(co * COUNTRIES[country].k, COUNTRIES[country].cur));

